import json,pathlib,xml.etree.ElementTree as E
root=pathlib.Path(__file__).resolve().parents[1];file=root/'dist/data.json';d=json.loads(file.read_text());by={q['id']:q for q in d['quests']}
def wiki(name):return 'https://witcher.fandom.com/wiki/'+name.replace(' ','_')
def add(id,title,options,source=None,note=None):
 q=by[id];url=source or wiki(q['name']);n={'id':id+'-d'+str(len(q['decisions'])+1),'title':title,'options':[{'label':a,'effect':b,'links':c} for a,b,c in options],'source':{'label':'分支依据：Witcher Wiki','url':url},'note':note or ''};q['decisions'].append(n);q['reviewed']=True
 if not any(s['url']==url for s in q['sources']):q['sources'].append({'label':'分支核对来源','url':url})
add('q37','是否把纵火犯交给铁匠',[('拒绝贿赂，带回纳普','威利斯把纳普交给尼弗迦德士兵。攻略描述他很可能被绞死；这是后果推断，任务没有直接展示行刑。',[]),('收受贿赂，放走纳普','放过纵火犯，放弃把他交回铁匠的路线。',[])])
by['q37']['trigger']='阅读白果园告示板，或直接与铁匠威利斯交谈。';by['q37']['cutoff']='在离开白果园、前往维吉玛前完成'
add('q36','面对商人的谎言',[('直接归还货物，不追问','得到普通报酬，任务结束，不揭穿他的身份。',[]),('揭穿并追上他，交给尼弗迦德','发现他是泰莫利亚游击队员；把他交给占领军。',[]),('揭穿并追上他，放人并归还货物','允许他带走军需物资，支持他的抵抗活动。',[]),('揭穿并追上他，放人但留下货物','放过游击队员，自己留下货物；报酬与物品不同。',[])],note='揭穿后必须追上他；追丢会导致任务失败。')
add('q19','是否救下尼弗迦德伤兵',[('先找杜恩，并劝他收留罗斯恩','巴斯蒂安和罗斯恩都得到帮助；之后可在杜恩家的农场找到他们。',[]),('认为收留逃兵太危险','巴斯蒂安获救，罗斯恩被留在小屋中死去。',[]),('先找到小屋，再去通知杜恩','杜恩只救走兄弟；杰洛特失去当场替罗斯恩说情的机会。',[])])
by['q19']['trigger']='白果园告示板或洗劫村庄的杜恩；先与杜恩交谈会保留完整结尾选择。';by['q19']['cutoff']='离开白果园前完成'
add('q40','模拟《巫师2》存档：雷索的命运',[('雷索在前作存活','里尔顿庄园可出现“往日的幽灵”，完成后能邀请雷索去凯尔莫罕。',['q83']),('雷索在前作死亡','雷索不会出现，“往日的幽灵”不可接取。',[])],note='仅在开启模拟存档时通过对话选择；导入真实存档时由存档状态决定。')
add('q83','完成雷索的计划后，是否邀请他',[('邀请去凯尔莫罕','雷索会在凯尔莫罕之战中协助。是否杀掉追兵不改变这个邀请选项。',['q257']),('不邀请，告别','雷索离开，之后不会作为凯尔莫罕援军出现。',[])],note='雷索必须在《巫师2》导入／模拟存档中存活；同行途中离开太远可能提前结束任务。')
add('q93','调查狂野之心',[('接受玛格丽特的贿赂，停止调查','掩盖失踪真相并提前收尾。后续村民对白会提到悲剧。',[]),('继续调查，阻止狼人杀她','杀死尼伦，玛格丽特活着离开。',[]),('继续调查，让狼人复仇','玛格丽特被杀，随后按尼伦的请求结束他的生命。',[])])
add('q80','如何解除费克岛的诅咒',[('把安娜贝的遗骨带给葛拉汉','瘟疫妖女离开塔，葛拉汉被杀；并不是让两人平安团聚的路线。',['q81']),('拒绝带遗骨，带葛拉汉到塔里','葛拉汉亲吻安娜贝后死亡，但诅咒被解除，妖女得到安息。',['q81'])])
add('q99','凯拉打算用研究笔记与拉多维德交易',[('劝她改去凯尔莫罕','凯拉存活，参加堡垒保卫战，并能救下兰伯特。',['q247','q257']),('允许她去见拉多维德','凯拉被处死，之后可出现“最后的善举”；她不会成为援军。',['q144']),('争执升级，强行夺取笔记','引发战斗，凯拉死亡；失去招募她的机会。',[])],note='一条安全说服路径：讨论笔记 → 拉多维德不会忘记 → 这等于自杀 → 提议凯尔莫罕。对白汉化可能不同。')
add('q74','如何处理尸婴',[('命名并埋葬，转化为家事妖精','保护男爵把尸婴带回门槛下安葬，再跟随家事妖精寻找家人。这个选择主要改变调查过程。',['q67','q107']),('杀死尸婴','收集血液，借助卜梦者的仪式寻找家人。男爵家庭的最终命运仍主要取决于树灵的选择。',['q67','q107'])],note='不要把尸婴的选择当作决定安娜与男爵结局的开关。')
add('q67','树灵：选择与执行时机',[('按“林中夫人”流程杀死或欺骗树灵','下瓦伦保住；孤儿被老巫妪带走，极可能被吃掉。安娜精神崩溃，男爵带她离开求医。',['q107']),('接到长老委托后释放树灵','树灵救下孤儿，并袭击下瓦伦。老巫妪把安娜变为水鬼；即使解除诅咒她也会死亡，男爵随后自尽。',['q107']),('在咨询长老前提前释放树灵','下瓦伦仍被袭击，安娜不会变成水鬼。攻略未找到通常用于证实孤儿获救的诺维格瑞记录；不能据此宣称所有人都获救。',['q107'])],note='任务执行时机很关键。提前释放路线没有实机复测，网站保留来源的证据边界。')
add('q107','当安娜已被变为水鬼：选择诅咒娃娃',[('选择带蜀葵花的娃娃','解除诅咒，安娜短暂恢复人形后死亡；男爵仍会自尽。',['q67']),('选择其他娃娃','安娜以怪物形态燃烧死亡；男爵仍会自尽。',['q67'])],note='这一节点仅适用于常规释放树灵后出现的诅咒路线。')
add('q145','花园中是否亲吻特莉丝',[('亲吻特莉丝','保留在“逃出生天”中锁定特莉丝恋情的前提。亲吻本身尚未锁定长期关系。',['q182']),('不亲吻','按攻略记录，之后无法用“逃出生天”的告白留住她。',['q182'])],source=wiki('A Matter of Life and Death (The Witcher 3)'))
by['q145']['sources']=[s for s in by['q145']['sources'] if s['url']!=wiki('A Matter of Life and Death')]
add('q147','卓尔坦给出两种报酬',[('选择昆特牌','得到三张稀有卡牌，有助于“收集所有卡牌”。',['collect']),('选择金币','得到金钱，放弃此处的卡牌奖励。',['collect'])])
add('q182','码头告别：是否锁定特莉丝恋情',[('请她留下，并说“我爱你”','若已在“生死交关”亲吻她，会锁定恋情；与叶奈法同时锁定会失去两段关系。',['q200','q25']),('告别，或未满足前序亲吻条件','特莉丝随法师们离开，杰洛特与她不进入长期恋情。',['q200'])],note='只说“留下来”不足以保证恋情。必须同时满足前序亲吻与本任务告白。')
add('q200','解开精灵的束缚后，如何回答叶奈法',[('表达仍然爱她','锁定叶奈法恋情；若也锁定特莉丝，会触发“三人探戈”。',['q182','q25']),('表示感情已消失','关系回到朋友，不锁定叶奈法恋情。',[])],source=wiki('The Last Wish (quest)'))
by['q200']['sources']=[s for s in by['q200']['sources'] if s['url']!=wiki('The Last Wish')]
add('q25','两段长期恋情的组合',[('同时锁定特莉丝和叶奈法','“最后的准备”期间触发三人探戈；最终不会与其中任一人维持长期恋情。',['q182','q200']),('只锁定一人','不会触发两人联手的这一支线剧情。',['q182','q200'])],source=wiki('Now or Never'))
add('q208','遇到纳撒尼尔后是否先听解释',[('先问清楚，追查真正的凶手','得到休伯特的线索，再到仓库击败他。问清后处理纳撒尼尔的方式不影响追查。',[]),('不听解释，直接杀死纳撒尼尔','无法继续追杀休伯特；真正的凶手逃脱，后续可发现反证。',[])])
add('q141','在七只猫旅馆推进兰伯特的线索',[('先处理史凯利杰“人口贩卖”','保留这项容易错过的支线，再回来与兰伯特交谈。',['q133']),('先与兰伯特交谈推进循线追查','“人口贩卖”将不可接取。',['q133'])],source=wiki('Flesh for Sale'))
by['q133']['cutoff']='在“循线追查”中于七只猫旅馆与兰伯特交谈前处理'
add('q268','是否放过猫派狩魔猎人盖坦',[('放过盖坦','开启“拿走你想要的”，可去他的藏身处领取报酬。',['q267']),('杀死盖坦','获得他的宝剑，但不再开启藏身处报酬任务。',[])],note='这一任务一旦触发，需要就地处理；离开区域可能失败。')
add('q214','解决附身怪物的两种方法',[('相信凯瑞丝，按计划把婴儿放进烤炉','婴儿被另一侧的海约特安全接走。海姆被骗并被放逐，乌达瑞克获救。',['q219']),('直接与海姆战斗','通过狩魔猎人的战斗方式解除乌达瑞克的折磨，同样能继续国王竞逐线。',['q219'])],source=wiki('Possession (quest)'))
add('q219','宴会之后支持谁调查',[('帮助凯瑞丝','查明宴会阴谋，凯瑞丝成为女王；史凯利杰更偏向和平发展。',['q220']),('帮助哈尔玛','走战斗调查路线，哈尔玛成为国王；继续对尼弗迦德的战争。',['q220']),('不帮助两人，或错过任务','斯凡瑞吉掌权。不会得到凯瑞丝／哈尔玛的这条加冕路线。',[])])
add('q235','安慰希里的方式',[('与她打雪仗','计为一次积极互动，增强她的信心。',['q298']),('劝她不必事事擅长，一起喝酒','计为一次消极互动。',['q298'])],source=wiki('Blood on the Battlefield'))
add('q235','去见恩希尔，还是直接去威伦',[('先带希里去见恩希尔','开启觐见和收钱／拒绝收钱的选择。只有她最终归来且尼弗迦德获胜时，才会成为女皇。',['q301','q298']),('直接去威伦','不发生收钱节点；若希里归来，她会成为狩魔猎人。',['q298'])],source=wiki('Something Ends, Something Begins (quest)'))
add('q235','如果见了恩希尔：是否收下酬金',[('拒绝酬金','计为一次积极互动。',['q298']),('收下酬金','计为一次消极互动。单独这一项不会自动导致她死亡，也不会单独排除女皇结局。',['q298'])],source=wiki('Something Ends, Something Begins (quest)'),note='只有选择带希里去见恩希尔时，才存在这个记分节点。')
add('q6','希里去见女术士集会',[('让她独自去','计为积极互动；叶奈法后来旁听不改变你的这个选择。',['q298']),('陪她一起去','计为消极互动，削弱希里独立处理事务的信心。',['q298'])])
add('q306','希里在阿瓦拉克实验室生气时',[('支持她发泄、砸毁实验室','计为一次积极互动。',['q298']),('让她冷静下来','计为一次消极互动。',['q298'])],source=wiki('Something Ends, Something Begins (quest)'))
add('q306','是否陪希里去祭拜史凯裘',[('答应陪她去','开启“史凯裘的坟墓”，计为积极互动。',['q286','q298']),('表示没有时间','不进行祭拜，计为消极互动。',['q298'])],source=wiki('Something Ends, Something Begins (quest)'))
add('q287','迪科斯彻拦路时',[('外交处理，交换恩希尔的情报','若已完成三项刺杀前置，开启“为祖国”。',['q186','q148','q146','q301']),('强行推开／伤害迪科斯彻','不再开启“为祖国”，拉多维德赢得战争。',['q301','q298'])],note='外交对白与三项前置都需要满足，不能只做其中之一。')
add('q301','战争与泰莫利亚的命运',[('刺杀后保护罗契、薇丝和塔勒','迪科斯彻死亡，尼弗迦德赢得战争；泰莫利亚成为附庸。可满足希里女皇结局的战争条件。',['q298']),('刺杀后离开，任由迪科斯彻处理他们','罗契、薇丝、塔勒死亡，迪科斯彻统治北方并赢得战争；希里不会成为尼弗迦德女皇。',['q298']),('不完成刺杀线','拉多维德统治北方并获胜；女皇结局的战争条件不满足。',['q298'])],source=wiki('The Witcher 3 decision checklist'))
add('q249','跨过主线进度门槛',[('先清理人物支线，再接受入岛警告','保留完成恋爱线、凯拉、史凯利杰王位和援军线的机会。',['q99','q182','q219','q186','q83']),('接受警告，直接继续','一批尚未完成的人物支线会失败或不可再接取。包括“逃出生天”“国王的赌局”等。',['q182','q219','q208'])],source=wiki('The Isle of Mists (quest)'),note='列表是重点任务提示，不是所有会被锁定的任务。完整清单见来源。')
add('q332','是否取走爱丽丝的紫色玫瑰',[('取走玫瑰','画中世界崩塌，爱丽丝的存在结束，猫与狗获得解脱。可交付真实玫瑰。',['q361']),('留下玫瑰','爱丽丝继续沉睡，守护者仍留在那里；带回玫瑰画像也能完成欧吉尔德的愿望。',['q361'])],note='这项选择不会替代终章关于欧吉尔德的选择。')
add('q361','先调查镜子大师，再做最终选择',[('找夏妮，并与夏克斯洛教授交谈','得知可以以谜题赌局挑战镜子大师，解锁救欧吉尔德的路线。',[]),('跳过教授，直接赴莉瓦尼神殿','失去正常流程中介入救欧吉尔德的机会，镜子大师取走他的灵魂。',[])])
add('q361','教授调查完成后：是否介入',[('挑战镜子大师并解开谜题','欧吉尔德获救，杰洛特得到“爱丽丝”钢剑。若谜题超时，杰洛特死亡，需要读档。',[]),('不介入，任由契约履行','欧吉尔德的灵魂被取走，可选择镜子大师给出的报酬。',[])],note='挑战选项依赖上一个节点的教授调查。谜题答案需要寻找不会被打碎的倒影。')
add('q366','如何对待斑纹妖鬼',[('充分调查诅咒后，选择不使用汤匙进食','解除诅咒，玛琳娜恢复人形；救助她后可在白鸦葡萄园开启“饥饿游戏”。',['q389']),('攻击并杀死妖鬼','取得主线所需材料，失去救助玛琳娜与后续支线的机会。',[]),('尝试解咒，但选择错误的餐具选项','没有解除诅咒，但已取得酿液，可继续主线；并不强制要求追杀妖鬼。',[])],note='隐藏前必须调查足够多的诅咒线索，才能出现解咒选项。')
add('q405','选择寻找席安娜，还是暗影长者',[('寻找戴米恩，追踪席安娜','进入儿童房，阅读家庭教师日记，再进入童话世界；保留姐妹和解的可能。',['q407']),('寻找欧丽安娜','先开启“血色简单”；完成后仍可反悔去找席安娜。真正进入长者洞穴才锁定另一条路线。',['q404','q406'])],note='在儿童房读前两条日记能满足后续关键知识条件；读完全部条目是稳妥的探索方式。')
add('q404','完成欧丽安娜的委托之后',[('继续寻找暗影长者','进入长者洞穴后锁定路线；之后无法促成姐妹和解。',['q406','q416']),('改变主意，去找席安娜','仍可进入童话世界路线；寻找欧丽安娜这一步本身不锁死结局。',['q407'])],source=wiki('The Night of Long Fangs'))
add('q407','是否取回卖火柴女孩的魔法缎带',[('购买或打昆特牌赢得缎带','缎带使席安娜逃过狄拉夫的致命攻击；狄拉夫会与杰洛特战斗。缎带仅保证这次生存，不能单独保证姐妹和解。',['q415','q416']),('不取回缎带','席安娜在泰沙姆穆那被狄拉夫杀死；随后可选择放走或与狄拉夫战斗。',['q415','q418'])],source=wiki('Little Flint Girl'))
add('q407','听席安娜讲述过去',[('倾听完整的故事','结合儿童房前两条日记，保留终章劝解她的必要条件。',['q416']),('拒绝倾听','即使有缎带，也缺少促成姐妹和解的条件。',['q416'])],source=wiki('Pomp and Strange Circumstance'))
add('q415','泰沙姆穆那的三种主要情形',[('童话路线，有缎带','席安娜暂时获救；必须击败狄拉夫，雷吉斯完成最终杀死他的动作。继续“盛典”。',['q416']),('童话路线，无缎带','席安娜死亡。可选择放狄拉夫离开或战斗，杰洛特进入牢狱路线。',['q418']),('通过暗影长者召来狄拉夫','必须与狄拉夫战斗。席安娜虽活到典礼，但这条路线无法促成姐妹和解。',['q416'])],source=wiki('Dettlaff van der Eretein'))
add('q416','如何促成姐妹和解',[('满足完整的前序条件并劝她宽恕','必须走童话路线、取得缎带、阅读儿童房前两条日记、听完席安娜的故事，再调查第五名受害者并用正确的牢房对白劝解。姐妹可以和解。',[]),('前序条件不全，或劝解失败','席安娜在典礼上杀死安娜，戴米恩射杀席安娜；两姐妹都死亡。',[])],note='劝解要围绕被遗忘的痛苦、宽恕姐妹和安娜年幼时无能为力。警告公爵夫人本身不能替代这些条件。')
add('q335','是否向纪尧姆透露薇薇恩的秘密',[('守住秘密，用黄鹂蛋解除诅咒','薇薇恩恢复自由，但剩余寿命被限制为约七年；这一路线证明“荣誉”。',['q424']),('透露秘密，让纪尧姆承接诅咒','纪尧姆自愿接受弱化的诅咒，两人结为伴侣。不是稍后随意改变的选择。',[])],note='比赛途中是否继续并赢得比武另有奖励，也可以证明“勇气”。')
add('q352','葡萄酒大战：何时揭露破坏者',[('交任务前，找到两家葡萄园的证据并完成幕后调查','揭露共同敌人，利亚姆与玛蒂达结束争执，联手经营贝尔迦德；后续可为新酒命名。',['q390','q378']),('只帮助一家，或先交付而未揭露破坏者','仍能推进葡萄园任务，但无法得到同样的和解与纪念酒结果。',['q353','q354'])],source=wiki('The Grapes of Wrath Stomped'))
